func p0JSON(value any) string { raw, _ := json.Marshal(value); return string(raw) }
func p0SSE(content string) string {
	return "data: " + p0JSON(map[string]any{"choices": []any{map[string]any{"delta": map[string]string{"content": content}}}}) + "\n\n"
}

func TestP0SchemaMatrix(t *testing.T) {
	_, candidate := p0Candidate()
	base := p0JSON(candidate)
	for _, tc := range []struct{ name, body, reason string }{
		{"empty", "", "candidate_empty"},
		{"encoding", string([]byte{0xff}), "candidate_encoding_invalid"},
		{"markdown", strings.Repeat(string(rune(96)), 3) + base, "passage_not_first"},
		{"order", strings.Replace(base, "{", "{\"extra\":1,", 1), "passage_not_first"},
		{"truncated", base[:len(base)-2], "json_invalid"},
		{"trailing", base + "{}", "json_trailing_content"},
		{"unknown_root", strings.Replace(base, "\"tags\":", "\"secret-key\":1,\"tags\":", 1), "candidate_keys_invalid"},
		{"duplicate", strings.Replace(base, "\"tags\":", "\"tags\":[],\"tags\":", 1), "json_duplicate_key"},
		{"null", strings.Replace(base, "\"tags\":[\"fruit\"]", "\"tags\":null", 1), "json_null"},
		{"unknown_target", strings.Replace(base, "\"source_entry\":", "\"secret-key\":1,\"source_entry\":", 1), "target_keys_invalid"},
		{"alias", strings.Replace(base, "\"entry_meaning\":", "\"Entry_Meaning\":", 1), "target_keys_invalid"},
		{"wrong_type", strings.Replace(base, "\"entry_meaning\":\"a small fruit\"", "\"entry_meaning\":3", 1), "json_invalid"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var good, got Candidate
			if err := decodeCandidateStrict([]byte(base), &good); err != nil {
				t.Fatal("positive control", err)
			}
			err := decodeCandidateStrict([]byte(tc.body), &got)
			d := DescribeFailure(err)
			if err == nil || d.Stage != "candidate_schema" || d.Reason != tc.reason {
				t.Fatalf("want %s got %+v", tc.reason, d)
			}
			if strings.Contains(err.Error(), "secret-key") {
				t.Fatal("private key in error")
			}
			if tc.name == "wrong_type" && d.Field != "entry_meaning" {
				t.Fatalf("type error field lost: %+v", d)
			}
		})
	}
	for _, tc := range []struct {
		name, reason, field string
		mutate              func(*Candidate)
	}{
		{"passage_empty", "passage_empty", "passage", func(c *Candidate) { c.Passage = "" }},
		{"tags_empty", "tag_count_invalid", "tags", func(c *Candidate) { c.Tags = []string{} }},
		{"tags_many", "tag_count_invalid", "tags", func(c *Candidate) { c.Tags = []string{"a", "b", "c", "d"} }},
		{"tag_empty", "tag_size_invalid", "tags", func(c *Candidate) { c.Tags[0] = "" }},
		{"tag_long", "tag_size_invalid", "tags", func(c *Candidate) { c.Tags[0] = strings.Repeat("a", 101) }},
		{"source_empty", "source_entry_size_invalid", "source_entry", func(c *Candidate) { c.Targets[1].SourceEntry = "" }},
		{"source_long", "source_entry_size_invalid", "source_entry", func(c *Candidate) { c.Targets[1].SourceEntry = strings.Repeat("a", 129) }},
		{"meaning_empty", "meaning_size_invalid", "entry_meaning", func(c *Candidate) { c.Targets[1].EntryMeaning = "" }},
		{"meaning_long", "meaning_size_invalid", "entry_meaning", func(c *Candidate) { c.Targets[1].EntryMeaning = strings.Repeat("a", 501) }},
		{"hint_empty", "hint_size_invalid", "hint_phrase", func(c *Candidate) { c.Targets[1].HintPhrase = "" }},
		{"hint_long", "hint_size_invalid", "hint_phrase", func(c *Candidate) { c.Targets[1].HintPhrase = strings.Repeat("a", maxAnnotatedHintRunes+1) }},
		{"body_limit", "candidate_byte_limit", "", func(c *Candidate) { c.Passage = strings.Repeat("a", maxCandidateBytes) }},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, c := p0Candidate()
			tc.mutate(&c)
			var got Candidate
			err := decodeCandidateStrict([]byte(p0JSON(c)), &got)
			d := DescribeFailure(err)
			if err == nil || d.Reason != tc.reason || d.Field != tc.field {
				t.Fatalf("want %s/%s got %+v", tc.reason, tc.field, d)
			}
			if (tc.field == "source_entry" || tc.field == "entry_meaning" || tc.field == "hint_phrase") && d.Target != 1 {
				t.Fatal("target index lost")
			}
		})
	}
	_, boundary := p0Candidate()
	boundary.Tags = []string{strings.Repeat("a", 100)}
	boundary.Targets[0] = CandidateTarget{strings.Repeat("a", 128), strings.Repeat("文", 500), strings.Repeat("a", maxAnnotatedHintRunes)}
	var got Candidate
	if err := decodeCandidateStrict([]byte(p0JSON(boundary)), &got); err != nil {
		t.Fatal("legal boundary", err)
	}
}

func TestP0ProviderStreamMatrix(t *testing.T) {
	_, candidate := p0Candidate()
	base := p0JSON(candidate)
	for _, tc := range []struct{ name, body, reason string }{
		{"no_done", p0SSE(base), ""},
		{"done", p0SSE(base) + "data: [DONE]\n\n", ""},
		{"no_newline", strings.TrimSpace(p0SSE(base)), ""},
		{"comments", ": heartbeat\nevent: ignored\n\n" + p0SSE(base), ""},
		{"empty_choices", "data: {\"choices\":[]}\n\n" + p0SSE(base), ""},
		{"empty", "", "candidate_empty"},
		{"early_done", "data: [DONE]\n\n", "candidate_empty"},
		{"invalid_event", "data: not JSON\n\n", "sse_event_json_invalid"},
		{"truncated", p0SSE(base[:len(base)-2]), "json_invalid"},
		{"unclosed_annotation", p0SSE("{\"passage\":\"grape(grape\"}"), "annotation_syntax_invalid"},
		{"two_candidates", p0SSE(base) + p0SSE(base), "json_trailing_content"},
		{"repeat_done", p0SSE(base) + "data: [DONE]\n\ndata: [DONE]\n\n", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			stream := openRouterStream{io.NopCloser(strings.NewReader(tc.body))}
			var preview strings.Builder
			got, err := stream.Receive(context.Background(), func(s string) error { preview.WriteString(s); return nil })
			if tc.reason == "" {
				if err != nil || got.Passage != candidate.Passage || preview.String() != "Young people share grapes and another grape." {
					t.Fatalf("legal stream failed: %v", err)
				}
			} else if err == nil || DescribeFailure(err).Reason != tc.reason {
				t.Fatalf("want %s got %+v", tc.reason, DescribeFailure(err))
			}
			if strings.Contains(preview.String(), "(grape)") || strings.Contains(preview.String(), "(young)") {
				t.Fatal("annotation leaked")
			}
		})
	}
	for _, tc := range []struct {
		status   int
		category FailureCategory
		retry    bool
	}{
		{401, FailureAuthentication, false}, {403, FailureAuthorization, false}, {404, FailureAuthorization, false},
		{429, FailureRateLimited, true}, {400, FailureUnavailable, false}, {500, FailureUnavailable, true}, {502, FailureUnavailable, true},
	} {
		t.Run("status_"+strconv.Itoa(tc.status), func(t *testing.T) {
			wire := "data: " + p0JSON(map[string]any{"error": map[string]any{"code": tc.status, "message": "private provider content"}}) + "\n\n"
			stream := openRouterStream{io.NopCloser(strings.NewReader(wire))}
			_, err := stream.Receive(context.Background(), func(string) error { t.Fatal("error streamed"); return nil })
			var p *ProviderError
			if !errors.As(err, &p) || p.Category != tc.category || p.Retryable != tc.retry || strings.Contains(p.Error(), "private") {
				t.Fatal("provider mapping/privacy")
			}
		})
	}
	stream := openRouterStream{io.NopCloser(strings.NewReader(p0SSE(base)))}
	callbackErr := errors.New("synthetic failure")
	if _, err := stream.Receive(context.Background(), func(string) error { return callbackErr }); !errors.Is(err, callbackErr) {
		t.Fatal("callback swallowed")
	}
	stream = openRouterStream{io.NopCloser(p0BrokenReader{})}
	if _, err := stream.Receive(context.Background(), func(string) error { return nil }); DescribeFailure(err).Reason != "sse_read_failed" {
		t.Fatal("reader failure")
	}
}

type p0BrokenReader struct{}

func (p0BrokenReader) Read([]byte) (int, error) { return 0, io.ErrUnexpectedEOF }

func TestP0RandomUnicodeStreamInvariant(t *testing.T) {
	const passage = "🙂 Café grapes(grape), a \"grape(grape)\".\n(Fresh grapes(grape).)"
	const clean = "🙂 Café grapes, a \"grape\".\n(Fresh grapes.)"
	candidate := Candidate{passage, []string{"fruit"}, []CandidateTarget{{"grape", "a fruit", "fresh grapes(grape)"}}}
	for seed := uint64(0); seed < 64; seed++ {
		rng := rand.New(rand.NewPCG(seed, 123))
		raw := strings.ReplaceAll(p0JSON(candidate), "🙂", "\\ud83d\\ude42")
		var wire strings.Builder
		for len(raw) > 0 {
			n := min(len(raw), rng.IntN(13)+1)
			for n < len(raw) && raw[n]&0xc0 == 0x80 {
				n++
			}
			wire.WriteString(p0SSE(raw[:n]))
			raw = raw[n:]
		}
		stream := openRouterStream{io.NopCloser(strings.NewReader(wire.String()))}
		var preview strings.Builder
		_, err := stream.Receive(context.Background(), func(delta string) error {
			preview.WriteString(delta)
			if !strings.HasPrefix(clean, preview.String()) {
				return errors.New("prefix mismatch")
			}
			return nil
		})
		if err != nil || preview.String() != clean {
			t.Fatalf("seed %d: %v", seed, err)
		}
	}
}

func FuzzP0CandidateDecoder(f *testing.F) {
	_, c := p0Candidate()
	f.Add(p0JSON(c))
	f.Add("{")
	f.Add("{\"passage\":null}")
	f.Fuzz(func(t *testing.T, raw string) {
		if len(raw) > 8192 {
			return
		}
		var c Candidate
		err := decodeCandidateStrict([]byte(raw), &c)
		if err != nil && DescribeFailure(err).Reason == "unknown_internal" {
			t.Fatal("unclassified decoder error")
		}
	})
}

package ai

import (
	"context"
	"io"
	"strings"
	"testing"
)

// Keep root ordering explicit: passage is a stream-owned first field.
func boundaryDocument(keys, values []string) string {
	parts := make([]string, len(keys))
	for i, key := range keys {
		parts[i] = p0JSON(key) + ":" + values[i]
	}
	return "{" + strings.Join(parts, ",") + "}"
}

func TestBoundarySchemaEveryField(t *testing.T) {
	_, candidate := p0Candidate()
	rootKeys := []string{"passage", "tags", "targets"}
	rootValues := []string{p0JSON(candidate.Passage), p0JSON(candidate.Tags), p0JSON(candidate.Targets)}
	targetKeys := []string{"source_entry", "entry_meaning", "hint_phrase"}
	targetValues := []string{p0JSON(candidate.Targets[0].SourceEntry), p0JSON(candidate.Targets[0].EntryMeaning), p0JSON(candidate.Targets[0].HintPhrase)}
	check := func(t *testing.T, raw, reason string) {
		t.Helper()
		var got Candidate
		err := decodeCandidateStrict([]byte(raw), &got)
		d := DescribeFailure(err)
		if err == nil || d.Stage != "candidate_schema" || d.Reason != reason {
			t.Fatalf("want %s; got %+v", reason, d)
		}
	}
	var valid Candidate
	if err := decodeCandidateStrict([]byte(boundaryDocument(rootKeys, rootValues)), &valid); err != nil {
		t.Fatal(err)
	}
	for _, level := range []string{"root", "target"} {
		keys, values := rootKeys, rootValues
		if level == "target" {
			keys, values = targetKeys, targetValues
		}
		for index, key := range keys {
			for _, mutation := range []string{"missing", "duplicate", "alias", "null", "type"} {
				t.Run(level+"/"+key+"/"+mutation, func(t *testing.T) {
					kk, vv := append([]string(nil), keys...), append([]string(nil), values...)
					reason := "candidate_keys_invalid"
					if level == "target" {
						reason = "target_keys_invalid"
					}
					switch mutation {
					case "missing":
						kk = append(kk[:index], kk[index+1:]...)
						vv = append(vv[:index], vv[index+1:]...)
					case "duplicate":
						kk = append(kk, key)
						vv = append(vv, values[index])
						reason = "json_duplicate_key"
					case "alias":
						kk[index] = strings.ToUpper(key)
					case "null":
						vv[index] = "null"
						reason = "json_null"
					case "type":
						vv[index] = "false"
						reason = "json_invalid"
						if key == "targets" {
							reason = "targets_type_invalid"
						}
					}
					if level == "root" && key == "passage" && mutation != "duplicate" {
						reason = "passage_not_first"
					}
					raw := boundaryDocument(kk, vv)
					if level == "target" {
						rv := append([]string(nil), rootValues...)
						rv[2] = "[" + raw + "," + p0JSON(candidate.Targets[1]) + "]"
						raw = boundaryDocument(rootKeys, rv)
					}
					check(t, raw, reason)
				})
			}
		}
	}
}

func TestBoundarySSEFraming(t *testing.T) {
	_, candidate := p0Candidate()
	wire := p0SSE(p0JSON(candidate))
	for _, prefix := range []string{"data:\n\n", ": ping\r\n\r\n", "event: message\nid: 1\nretry: 1000\n\n"} {
		for _, crlf := range []bool{false, true} {
			body := prefix + wire
			if crlf {
				body = strings.ReplaceAll(body, "\n", "\r\n")
			}
			stream := openRouterStream{io.NopCloser(strings.NewReader(body))}
			var clean strings.Builder
			got, err := stream.Receive(context.Background(), func(s string) error { clean.WriteString(s); return nil })
			if err != nil || got.Passage != candidate.Passage || clean.String() != "Young people share grapes and another grape." {
				t.Fatalf("valid SSE framing: %v", err)
			}
		}
	}
}

func TestBoundarySSEInvalidUTF8RejectedBeforeReplacement(t *testing.T) {
	_, candidate := p0Candidate()
	wire := strings.Replace(p0SSE(p0JSON(candidate)), "people", "pe"+string([]byte{0xff})+"ple", 1)
	stream := openRouterStream{io.NopCloser(strings.NewReader(wire))}
	var preview strings.Builder
	_, err := stream.Receive(context.Background(), func(s string) error { preview.WriteString(s); return nil })
	if DescribeFailure(err).Reason != "sse_event_encoding_invalid" || preview.Len() != 0 {
		t.Fatalf("invalid wire encoding was silently replaced: %+v; emitted=%d", DescribeFailure(err), preview.Len())
	}
}

func TestBoundaryMultipleCompleteChoicesAreNotMergedAsValid(t *testing.T) {
	_, candidate := p0Candidate()
	choice := map[string]any{"delta": map[string]string{"content": p0JSON(candidate)}}
	wire := "data: " + p0JSON(map[string]any{"choices": []any{choice, choice}}) + "\n\n"
	stream := openRouterStream{io.NopCloser(strings.NewReader(wire))}
	_, err := stream.Receive(context.Background(), func(string) error { return nil })
	if DescribeFailure(err).Reason != "json_trailing_content" {
		t.Fatalf("two complete choices accepted as one result: %v", err)
	}
}

func TestBoundaryMinimumWordThreshold(t *testing.T) {
	validator := testValidator(t)
	for _, minimum := range []int{6, 7, 8} {
		spec, candidate := p0Candidate() // independently counted: seven clean words
		spec.MinimumWords = minimum
		batch, err := validator.Validate(context.Background(), spec, candidate)
		if minimum <= 7 {
			if err != nil || batch.WordCount != 7 {
				t.Fatalf("legal boundary: %v", err)
			}
		} else {
			detail := DescribeFailure(err)
			if detail.Reason != "passage_too_short" || detail.Actual != 7 || detail.Limit != 8 {
				t.Fatal("wrong word-count boundary")
			}
		}
	}
}

package ai

import (
	"encoding/json"
	"errors"
	"slices"
	"strings"
	"unicode/utf8"
)

var errSnapshot = errors.New("invalid current validated snapshot")

// DecodeSnapshot accepts only the current persisted shape. It verifies stored
// structure and spans, never reselects a meaning or reruns lexical validation.
func DecodeSnapshot(raw []byte) (ValidatedBatch, error) {
	var batch ValidatedBatch
	if !utf8.Valid(raw) || rejectDuplicateJSONKeys(raw) != nil {
		return batch, errSnapshot
	}
	var object map[string]json.RawMessage
	if json.Unmarshal(raw, &object) != nil || !exactObjectKeys(object, []string{"passage", "tags", "targets", "word_count", "validator_version"}) {
		return batch, errSnapshot
	}
	var targets []map[string]json.RawMessage
	if json.Unmarshal(object["targets"], &targets) != nil {
		return batch, errSnapshot
	}
	for _, target := range targets {
		if !exactObjectKeys(target, []string{"entry", "entry_meaning", "hint_phrase", "hint_occurrences", "passage_occurrences"}) {
			return batch, errSnapshot
		}
		for _, field := range []string{"hint_occurrences", "passage_occurrences"} {
			var spans []map[string]json.RawMessage
			if json.Unmarshal(target[field], &spans) != nil || len(spans) == 0 {
				return batch, errSnapshot
			}
			for _, span := range spans {
				if !exactObjectKeys(span, []string{"surface", "start", "end"}) ||
					string(span["start"]) == "null" || string(span["end"]) == "null" {
					return batch, errSnapshot
				}
			}
		}
	}
	if json.Unmarshal(raw, &batch) != nil || ValidateSnapshot(batch) != nil {
		return ValidatedBatch{}, errSnapshot
	}
	return batch, nil
}

func validEntryMeaning(value string) bool {
	return utf8.ValidString(value) && value != "" && strings.TrimSpace(value) == value && utf8.RuneCountInString(value) <= 500
}

// ValidateSnapshot is shared by the writer and reader. Semantic/language and
// lexical decisions belong exclusively to the initial candidate validator.
func ValidateSnapshot(batch ValidatedBatch) error {
	if batch.Passage == "" || !utf8.ValidString(batch.Passage) || batch.WordCount < 1 ||
		batch.ValidatorVersion == "" || len(batch.Targets) == 0 || len(batch.Tags) < 1 || len(batch.Tags) > 3 {
		return errSnapshot
	}
	for _, tag := range batch.Tags {
		if tag == "" || strings.TrimSpace(tag) != tag || utf8.RuneCountInString(tag) > 100 {
			return errSnapshot
		}
	}
	entries := make(map[string]bool, len(batch.Targets))
	var all []Occurrence
	for _, target := range batch.Targets {
		if target.Entry == "" || strings.TrimSpace(target.Entry) != target.Entry || entries[target.Entry] ||
			!validEntryMeaning(target.EntryMeaning) || target.HintPhrase == "" ||
			!validStoredSpans(target.HintPhrase, target.HintOccurrences) ||
			!validStoredSpans(batch.Passage, target.PassageOccurrences) {
			return errSnapshot
		}
		entries[target.Entry] = true
		all = append(all, target.PassageOccurrences...)
	}
	slices.SortFunc(all, func(a, b Occurrence) int { return a.Start - b.Start })
	if !validStoredSpans(batch.Passage, all) {
		return errSnapshot
	}
	return nil
}

func validStoredSpans(text string, spans []Occurrence) bool {
	if len(spans) == 0 || !utf8.ValidString(text) {
		return false
	}
	runes, previous := []rune(text), 0
	for _, span := range spans {
		if span.Start < previous || span.End <= span.Start || span.End > len(runes) ||
			string(runes[span.Start:span.End]) != span.Surface {
			return false
		}
		previous = span.End
	}
	return true
}

