func annotationFixture(t *testing.T) (string, captureTicket, ai.GenerationSpec, ai.Candidate) {
	t.Helper()
	dir, ticket, spec, candidate := captureFixture(t)
	t.Setenv("UAT_FAILURE_CAPTURE_DIR", "")
	t.Setenv("UAT_ANNOTATION_CAPTURE_DIR", dir)
	candidate.Passage = "Private surrounding sentence. Grapes(Grape) are ripe. More private text."
	candidate.Tags = []string{"private-tag"}
	candidate.Targets[0].EntryMeaning = "private-meaning"
	candidate.Targets[0].HintPhrase = "private-hint"
	return dir, ticket, spec, candidate
}

func assertNoAnnotation(t *testing.T, dir string) {
	t.Helper()
	if _, err := os.Stat(filepath.Join(dir, annotationCaptureFilename)); !os.IsNotExist(err) {
		t.Fatalf("unexpected annotation file: %v", err)
	}
	assertNoCapture(t, dir)
}

func TestAnnotationCaptureMinimalOutput(t *testing.T) {
	dir, _, spec, candidate := annotationFixture(t)
	capture := openTestCapture(t)
	var logs bytes.Buffer
	previous := slog.Default()
	slog.SetDefault(slog.New(slog.NewJSONHandler(&logs, nil)))
	defer slog.SetDefault(previous)
	capture.Record(captureTestSubject, spec, candidate, "annotation_source_unknown", -1)
	raw, err := os.ReadFile(filepath.Join(dir, annotationCaptureFilename))
	if err != nil {
		t.Fatal(err)
	}
	var sample map[string]json.RawMessage
	if json.Unmarshal(raw, &sample) != nil || len(sample) != 7 {
		t.Fatal("unexpected fields")
	}
	var annotation ai.AnnotationSourceDiagnostic
	if json.Unmarshal(sample["annotation"], &annotation) != nil || annotation.SourceLabel != "Grape" || annotation.AdjacentWord != "Grapes" {
		t.Fatal("wrong annotation projection")
	}
	for _, secret := range []string{"Private surrounding", "More private", "private-tag", "private-meaning", "private-hint", captureTestSubject, "candidate", "configuration", "generation_token", "api_key"} {
		if bytes.Contains(raw, []byte(secret)) || strings.Contains(logs.String(), secret) {
			t.Fatal("private content or metadata escaped allowlist")
		}
	}
	if strings.Contains(logs.String(), "Grape") || strings.Contains(logs.String(), dir) {
		t.Fatal("annotation or path leaked to logs")
	}
	for _, name := range []string{annotationCaptureFilename, annotationClaimFilename} {
		info, err := os.Stat(filepath.Join(dir, name))
		if err != nil || info.Mode().Perm() != 0o600 {
			t.Fatal("not private")
		}
	}
	assertNoCapture(t, dir)
	capture.Close()
	assertNoAnnotation(t, dir)
}

func TestAnnotationCaptureScopeConcurrencyAndRestart(t *testing.T) {
	dir, _, spec, candidate := annotationFixture(t)
	capture := openTestCapture(t)
	for _, reason := range []string{"mapping_surface_absent", "annotation_syntax_invalid", "annotation_target_mismatch"} {
		capture.Record(captureTestSubject, spec, candidate, reason, -1)
	}
	capture.Record("account:22222222-2222-4222-8222-222222222222", spec, candidate, "annotation_source_unknown", -1)
	other := spec
	other.ModelID = "another-model"
	capture.Record(captureTestSubject, other, candidate, "annotation_source_unknown", -1)
	other = spec
	other.CompatibilityProbe = true
	capture.Record(captureTestSubject, other, candidate, "annotation_source_unknown", -1)
	capture.Record(captureTestSubject, spec, candidate, "annotation_source_unknown", 0)
	valid := candidate
	valid.Passage = "grapes(grape)"
	capture.Record(captureTestSubject, spec, valid, "annotation_source_unknown", -1)
	assertNoAnnotation(t, dir)
	if _, err := os.Stat(filepath.Join(dir, annotationClaimFilename)); !os.IsNotExist(err) {
		t.Fatal("nonmatching request consumed the ticket")
	}
	var workers sync.WaitGroup
	for range 20 {
		workers.Go(func() { capture.Record(captureTestSubject, spec, candidate, "annotation_source_unknown", -1) })
	}
	workers.Wait()
	first, err := os.ReadFile(filepath.Join(dir, annotationCaptureFilename))
	if err != nil {
		t.Fatal(err)
	}
	candidate.Passage = "grapes(SECOND)"
	capture.Record(captureTestSubject, spec, candidate, "annotation_source_unknown", -1)
	after, err := os.ReadFile(filepath.Join(dir, annotationCaptureFilename))
	if err != nil || !bytes.Equal(first, after) {
		t.Fatal("sample overwritten")
	}
	// Simulates reading/deleting the private sample and then a same-ticket restart.
	if err := os.Remove(filepath.Join(dir, annotationCaptureFilename)); err != nil {
		t.Fatal(err)
	}
	capture.Close()
	reopened := openTestCapture(t)
	reopened.Record(captureTestSubject, spec, candidate, "annotation_source_unknown", -1)
	assertNoAnnotation(t, dir)
}

func TestAnnotationCaptureExpiryAndInvalidFiles(t *testing.T) {
	t.Run("expiry", func(t *testing.T) {
		dir, ticket, spec, candidate := annotationFixture(t)
		ticket.ExpiresAt = time.Now().Add(200 * time.Millisecond)
		writeCaptureTicket(t, dir, ticket)
		capture := openTestCapture(t)
		capture.Record(captureTestSubject, spec, candidate, "annotation_source_unknown", -1)
		deadline := time.Now().Add(3 * time.Second)
		for time.Now().Before(deadline) {
			if _, err := os.Stat(filepath.Join(dir, annotationCaptureFilename)); os.IsNotExist(err) {
				break
			}
			time.Sleep(10 * time.Millisecond)
		}
		assertNoAnnotation(t, dir)
		capture.Record(captureTestSubject, spec, candidate, "annotation_source_unknown", -1)
		assertNoAnnotation(t, dir)
	})
	for _, bad := range []string{"both_modes", "claim_symlink", "sample_symlink", "claim_permissions"} {
		t.Run(bad, func(t *testing.T) {
			dir, _, _, _ := annotationFixture(t)
			switch bad {
			case "both_modes":
				t.Setenv("UAT_FAILURE_CAPTURE_DIR", dir)
			case "claim_symlink":
				if err := os.Symlink("ticket.json", filepath.Join(dir, annotationClaimFilename)); err != nil {
					t.Fatal(err)
				}
			case "sample_symlink":
				if err := os.Symlink("ticket.json", filepath.Join(dir, annotationCaptureFilename)); err != nil {
					t.Fatal(err)
				}
			case "claim_permissions":
				if err := os.WriteFile(filepath.Join(dir, annotationClaimFilename), nil, 0o644); err != nil {
					t.Fatal(err)
				}
			}
			if got, err := newFailureCapture("http://localhost:6001"); got != nil || err == nil {
				t.Fatal("invalid configuration accepted")
			}
		})
	}
}

package httpapi

import (
	"errors"
	"net/http"
	"strconv"
	"time"

	"wordweave/internal/entitlement"
	"wordweave/internal/vocabulary"
)

func (server *Server) vocabularySearch(writer http.ResponseWriter, request *http.Request) {
	query := request.URL.Query().Get("q")
	limit := 10
	if raw := request.URL.Query().Get("limit"); raw != "" {
		parsed, err := strconv.Atoi(raw)
		if err != nil {
			writeProblem(writer, request, http.StatusBadRequest, "malformed_request", "Malformed request", "The limit parameter is invalid.")
			return
		}
		limit = parsed
	}
	result, err := server.vocabulary.Search(request.Context(), query, int32(limit))
	if err != nil {
		if errors.Is(err, vocabulary.ErrInvalidQuery) {
			writeProblem(writer, request, http.StatusUnprocessableEntity, "validation_failed", "Request could not be accepted", "The vocabulary query is invalid.")
			return
		}
		writeProblem(writer, request, http.StatusInternalServerError, "internal_error", "Internal error", "The request could not be completed.")
		return
	}
	items := make([]struct {
		Entry string `json:"entry"`
	}, 0, len(result.Items))
	for _, entry := range result.Items {
		items = append(items, struct {
			Entry string `json:"entry"`
		}{Entry: entry})
	}
	writeJSON(writer, request, http.StatusOK, struct {
		Items             any    `json:"items"`
		VocabularyVersion string `json:"vocabulary_version"`
	}{Items: items, VocabularyVersion: result.Version})
}

func (server *Server) generationOptions(writer http.ResponseWriter, request *http.Request) {
	actor, _ := actorFromContext(request.Context())
	options, err := server.entitlement.Options(request.Context(), actor)
	if err != nil {
		if errors.Is(err, entitlement.ErrForbidden) {
			writeProblem(writer, request, http.StatusForbidden, "forbidden", "Access denied", "Generation is not available for this account.")
			return
		}
		writeProblem(writer, request, http.StatusInternalServerError, "internal_error", "Internal error", "The request could not be completed.")
		return
	}
	type modelDTO struct {
		ID          string  `json:"id"`
		Name        string  `json:"name"`
		Description *string `json:"description"`
	}
	models := make([]modelDTO, 0, len(options.Models))
	for _, model := range options.Models {
		models = append(models, modelDTO{ID: model.ID, Name: model.Name, Description: model.Description})
	}
	type quotaDTO struct {
		Kind        string  `json:"kind"`
		Limit       *int    `json:"limit"`
		Remaining   *int    `json:"remaining"`
		WindowHours int     `json:"window_hours"`
		RefreshesAt *string `json:"refreshes_at"`
	}
	var refreshesAt *string
	if options.Quota.RefreshesAt != nil {
		value := options.Quota.RefreshesAt.Format(time.RFC3339)
		refreshesAt = &value
	}
	writeJSON(writer, request, http.StatusOK, struct {
		Models           []modelDTO `json:"models"`
		MeaningLanguages []string   `json:"meaning_languages"`
		Scenarios        []string   `json:"scenarios"`
		Lengths          []string   `json:"lengths"`
		MaxEntries       int        `json:"max_entries"`
		Availability     struct {
			CanGenerate bool    `json:"can_generate"`
			Reason      *string `json:"reason"`
		} `json:"availability"`
		Quota quotaDTO `json:"quota"`
	}{
		Models: models, MeaningLanguages: options.MeaningLanguages, Scenarios: options.Scenarios,
		Lengths: options.Lengths, MaxEntries: options.MaxEntries,
		Availability: struct {
			CanGenerate bool    `json:"can_generate"`
			Reason      *string `json:"reason"`
		}{CanGenerate: options.CanGenerate, Reason: options.Reason},
		Quota: quotaDTO{Kind: options.Quota.Kind, Limit: options.Quota.Limit, Remaining: options.Quota.Remaining, WindowHours: 24, RefreshesAt: refreshesAt},
	})
}

