func TestFailureCaptureUnavailableInNormalBuild(t *testing.T) {
	t.Setenv("UAT_FAILURE_CAPTURE_DIR", "/must-not-be-read")
	t.Setenv("UAT_ANNOTATION_CAPTURE_DIR", "/also-must-not-be-read")
	t.Setenv("UAT_HINT_CAPTURE_DIR", "/hint-must-not-be-read")
