	previous := slog.Default()
	slog.SetDefault(slog.New(slog.NewJSONHandler(&logs, nil)))
	defer slog.SetDefault(previous)
	capture.Record(captureTestSubject, spec, candidate, "mapping_surface_absent", 0)
	raw, err := os.ReadFile(filepath.Join(dir, captureFilename))
	if err != nil {
		t.Fatal(err)
	}
	var got struct {
		RunID       string       `json:"run_id"`
		Reason      string       `json:"reason"`
		TargetIndex int          `json:"target_index"`
		Candidate   ai.Candidate `json:"candidate"`
	}
	if json.Unmarshal(raw, &got) != nil || got.RunID != spec.RunID ||
		got.Reason != "mapping_surface_absent" || got.TargetIndex != 0 || !reflect.DeepEqual(got.Candidate, candidate) {
		t.Fatal("candidate or diagnosis changed during capture")
