	info, err := os.Stat(filepath.Join(dir, captureFilename))
	if err != nil || info.Mode().Perm() != 0o600 {
		t.Fatal("sample is not private")
	}
	for _, forbidden := range []string{"authorization", "generation_token", "account_id", "password", "api_key"} {
		if strings.Contains(string(raw), forbidden) {
			t.Fatalf("unexpected captured field: %s", forbidden)
