package httpapi

import (
	"bytes"
	"encoding/json"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"wordweave/internal/ai"
)

func hintFixture(t *testing.T) (string, captureTicket, ai.GenerationSpec, ai.Candidate) {
	t.Helper()
	dir, ticket, spec, candidate := captureFixture(t)
	t.Setenv("UAT_FAILURE_CAPTURE_DIR", "")
	t.Setenv("UAT_ANNOTATION_CAPTURE_DIR", "")
	t.Setenv("UAT_HINT_CAPTURE_DIR", dir)
	spec.Entries = []string{"grape", "melancholy"}
	candidate.Passage = "private-passage-must-not-be-captured"
	candidate.Tags = []string{"private-tag"}
	candidate.Targets[0].HintPhrase = "private-sibling-hint"
	candidate.Targets = append(candidate.Targets, ai.CandidateTarget{
		SourceEntry: "melancholy", EntryMeaning: "private-meaning",
		HintPhrase: "a melancholy (melancholy) mood",
	})
	return dir, ticket, spec, candidate
}

func assertNoHint(t *testing.T, dir string) {
	t.Helper()
	if _, err := os.Lstat(filepath.Join(dir, hintCaptureFilename)); !os.IsNotExist(err) {
		t.Fatalf("unexpected hint sample: %v", err)
	}
	assertNoAnnotation(t, dir)
}

func TestHintCaptureOnlyIndexedRawHint(t *testing.T) {
	for _, hint := range []string{"a melancholy mood", "a melancholy (melancholy) mood", "a melancholy（melancholy）mood"} {
		t.Run(hint, func(t *testing.T) {
			dir, _, spec, candidate := hintFixture(t)
			candidate.Targets[1].HintPhrase = hint
			capture := openTestCapture(t)
			var logs bytes.Buffer
			previous := slog.Default()
			slog.SetDefault(slog.New(slog.NewJSONHandler(&logs, nil)))
			defer slog.SetDefault(previous)
			capture.Record(captureTestSubject, spec, candidate, "hint_annotation_missing", 1)
			raw, err := os.ReadFile(filepath.Join(dir, hintCaptureFilename))
			if err != nil {
				t.Fatal(err)
			}
			var fields map[string]json.RawMessage
			var gotHint string
			var gotIndex int
			if json.Unmarshal(raw, &fields) != nil || len(fields) != 8 ||
				json.Unmarshal(fields["hint_phrase"], &gotHint) != nil || gotHint != hint ||
				json.Unmarshal(fields["target_index"], &gotIndex) != nil || gotIndex != 1 {
				t.Fatal("hint projection was not exact and minimal")
			}
			for _, forbidden := range []string{candidate.Passage, candidate.Tags[0], candidate.Targets[0].HintPhrase,
				candidate.Targets[1].EntryMeaning, captureTestSubject, "generation_token", "api_key", "candidate", "configuration"} {
				if bytes.Contains(raw, []byte(forbidden)) || strings.Contains(logs.String(), forbidden) {
					t.Fatal("capture exceeded approved scope")
				}
			}
			if strings.Contains(logs.String(), hint) || strings.Contains(logs.String(), dir) {
				t.Fatal("hint/path leaked to logs")
			}
			for _, name := range []string{hintCaptureFilename, hintClaimFilename} {
				info, err := os.Stat(filepath.Join(dir, name))
				if err != nil || info.Mode().Perm() != 0o600 {
					t.Fatal("file not private")
				}
			}
			assertNoAnnotation(t, dir)
			capture.Close()
			assertNoHint(t, dir)
		})
	}
}

func TestHintCaptureScopeConcurrencyAndRestart(t *testing.T) {
	dir, _, spec, candidate := hintFixture(t)
	capture := openTestCapture(t)
	for _, reason := range []string{"annotation_source_unknown", "annotation_syntax_invalid", "annotation_target_mismatch", "mapping_surface_absent"} {
		capture.Record(captureTestSubject, spec, candidate, reason, 1)
	}
	for _, index := range []int{-1, 2, 100} {
		capture.Record(captureTestSubject, spec, candidate, "hint_annotation_missing", index)
	}
	capture.Record("account:22222222-2222-4222-8222-222222222222", spec, candidate, "hint_annotation_missing", 1)
	other := spec
	other.ModelID = "another-model"
	capture.Record(captureTestSubject, other, candidate, "hint_annotation_missing", 1)
	other = spec
	other.CompatibilityProbe = true
	capture.Record(captureTestSubject, other, candidate, "hint_annotation_missing", 1)
	for _, bad := range []string{"", strings.Repeat("a", 501), string([]byte{0xff})} {
		c := candidate
		c.Targets = append([]ai.CandidateTarget(nil), candidate.Targets...)
		c.Targets[1].HintPhrase = bad
		capture.Record(captureTestSubject, spec, c, "hint_annotation_missing", 1)
	}
	c := candidate
	c.Targets = append([]ai.CandidateTarget(nil), candidate.Targets...)
	c.Targets[1].SourceEntry = "wrong"
	capture.Record(captureTestSubject, spec, c, "hint_annotation_missing", 1)
	assertNoHint(t, dir)
	if _, err := os.Lstat(filepath.Join(dir, hintClaimFilename)); !os.IsNotExist(err) {
		t.Fatal("unrelated request consumed ticket")
	}
	var workers sync.WaitGroup
	for range 20 {
		workers.Go(func() { capture.Record(captureTestSubject, spec, candidate, "hint_annotation_missing", 1) })
	}
	workers.Wait()
	first, err := os.ReadFile(filepath.Join(dir, hintCaptureFilename))
	if err != nil {
		t.Fatal(err)
	}
	candidate.Targets[1].HintPhrase = "do not overwrite"
	capture.Record(captureTestSubject, spec, candidate, "hint_annotation_missing", 1)
	next, err := os.ReadFile(filepath.Join(dir, hintCaptureFilename))
	if err != nil || !bytes.Equal(first, next) {
		t.Fatal("sample overwritten")
	}
	if err := os.Remove(filepath.Join(dir, hintCaptureFilename)); err != nil {
		t.Fatal(err)
	}
	capture.Close()
	reopened := openTestCapture(t)
	reopened.Record(captureTestSubject, spec, candidate, "hint_annotation_missing", 1)
	assertNoHint(t, dir)
}

func TestHintCaptureExpiryAndInvalidFiles(t *testing.T) {
	t.Run("expiry", func(t *testing.T) {
		dir, ticket, spec, candidate := hintFixture(t)
		ticket.ExpiresAt = time.Now().Add(200 * time.Millisecond)
		writeCaptureTicket(t, dir, ticket)
		capture := openTestCapture(t)
		capture.Record(captureTestSubject, spec, candidate, "hint_annotation_missing", 1)
		if _, err := os.Stat(filepath.Join(dir, hintCaptureFilename)); err != nil {
			t.Fatal(err)
		}
		deadline := time.Now().Add(3 * time.Second)
		for time.Now().Before(deadline) {
			if _, err := os.Stat(filepath.Join(dir, hintCaptureFilename)); os.IsNotExist(err) {
				break
			}
			time.Sleep(10 * time.Millisecond)
		}
		assertNoHint(t, dir)
		capture.Record(captureTestSubject, spec, candidate, "hint_annotation_missing", 1)
		assertNoHint(t, dir)
	})
	for _, bad := range []string{"full_mode", "annotation_mode", "claim_symlink", "sample_symlink", "claim_permissions", "expired"} {
		t.Run(bad, func(t *testing.T) {
			dir, ticket, _, _ := hintFixture(t)
			switch bad {
			case "full_mode":
				t.Setenv("UAT_FAILURE_CAPTURE_DIR", dir)
			case "annotation_mode":
				t.Setenv("UAT_ANNOTATION_CAPTURE_DIR", dir)
			case "claim_symlink":
				if err := os.Symlink("ticket.json", filepath.Join(dir, hintClaimFilename)); err != nil {
					t.Fatal(err)
				}
			case "sample_symlink":
				if err := os.Symlink("ticket.json", filepath.Join(dir, hintCaptureFilename)); err != nil {
					t.Fatal(err)
				}
			case "claim_permissions":
				if err := os.WriteFile(filepath.Join(dir, hintClaimFilename), nil, 0o644); err != nil {
					t.Fatal(err)
				}
			case "expired":
				ticket.ExpiresAt = time.Now().Add(-time.Second)
				writeCaptureTicket(t, dir, ticket)
			}
			got, err := newFailureCapture("http://localhost:6001")
			if bad == "expired" {
				if got != nil || err != nil {
					t.Fatal("expired capture active")
				}
				return
			}
			if got != nil || err == nil {
				t.Fatal("invalid capture configuration accepted")
			}
		})
	}
}

package httpapi

import (
	"errors"
	"net/http"
	"time"

	"wordweave/internal/identity"
)

type actorDTO struct {
	Kind     string  `json:"kind"`
	Username *string `json:"username"`
	Role     *string `json:"role"`
	PlanCode *string `json:"plan_code"`
}

type bootstrapDTO struct {
	Actor              actorDTO `json:"actor"`
	UILocale           *string  `json:"ui_locale"`
	SupportedUILocales []string `json:"supported_ui_locales"`
	CSRFToken          string   `json:"csrf_token"`
}

type authDTO struct {
	Actor     actorDTO `json:"actor"`
	UILocale  *string  `json:"ui_locale"`
	CSRFToken string   `json:"csrf_token"`
}

func (server *Server) bootstrap(writer http.ResponseWriter, request *http.Request) {
	actor, _ := actorFromContext(request.Context())
	server.writeBootstrapProjection(writer, request, actor)
}

func (server *Server) register(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		Username             string `json:"username"`
		Password             string `json:"password"`
		PasswordConfirmation string `json:"password_confirmation"`
		UILocale             string `json:"ui_locale"`
	}
	if !decodeOrProblem(writer, request, &body, 4096) {
		return
	}
	if !server.requireAuthRate(writer, request, "register", body.Username, 5, 12*time.Second) {
		return
	}
	actor, _ := actorFromContext(request.Context())
	registered, credential, err := server.identity.Register(request.Context(), actor, identity.RegisterInput{
		Username: body.Username, Password: body.Password,
		PasswordConfirmation: body.PasswordConfirmation, UILocale: body.UILocale,
	})
	if err != nil {
		server.writeIdentityProblem(writer, request, err, true)
		return
	}
	server.setSessionCookie(writer, credential)
	server.writeAuthProjection(writer, request, http.StatusCreated, registered)
}

func (server *Server) login(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		Username        string `json:"username"`
		Password        string `json:"password"`
		BrowserUILocale string `json:"browser_ui_locale"`
	}
	if !decodeOrProblem(writer, request, &body, 4096) {
		return
	}
	if !server.requireAuthRate(writer, request, "login", body.Username, 10, 6*time.Second) {
		return
	}
	actor, credential, err := server.identity.Login(request.Context(), identity.LoginInput{
		Username: body.Username, Password: body.Password, BrowserUILocale: body.BrowserUILocale,
	})
	if err != nil {
		server.writeIdentityProblem(writer, request, err, false)
		return
	}
	server.setSessionCookie(writer, credential)
	server.writeAuthProjection(writer, request, http.StatusOK, actor)
}

func (server *Server) logout(writer http.ResponseWriter, request *http.Request) {
	var body struct{}
	if !decodeOrProblem(writer, request, &body, 128) {
		return
	}
	actor, _ := actorFromContext(request.Context())
	if err := server.identity.Logout(request.Context(), actor); err != nil {
		server.writeIdentityProblem(writer, request, err, false)
		return
	}
	server.clearSessionCookie(writer)
	writeNoContent(writer)
}

func (server *Server) updateLocale(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		UILocale string `json:"ui_locale"`
	}
	if !decodeOrProblem(writer, request, &body, 256) {
		return
	}
	actor, _ := actorFromContext(request.Context())
	if err := server.identity.SetLocale(request.Context(), actor, body.UILocale); err != nil {
		server.writeIdentityProblem(writer, request, err, false)
		return
	}
	writeJSON(writer, request, http.StatusOK, struct {
		UILocale string `json:"ui_locale"`
	}{UILocale: body.UILocale})
}

func (server *Server) account(writer http.ResponseWriter, request *http.Request) {
	actor, _ := actorFromContext(request.Context())
	writeJSON(writer, request, http.StatusOK, struct {
		Username string  `json:"username"`
		PlanCode *string `json:"plan_code"`
		UILocale string  `json:"ui_locale"`
	}{Username: actor.Username, PlanCode: identity.PlanCode(actor.GroupCode), UILocale: dereference(actor.UILocale)})
}

func (server *Server) changePassword(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		CurrentPassword         string `json:"current_password"`
		NewPassword             string `json:"new_password"`
		NewPasswordConfirmation string `json:"new_password_confirmation"`
	}
	if !decodeOrProblem(writer, request, &body, 4096) {
		return
	}
	actor, _ := actorFromContext(request.Context())
	if !server.requireAuthRate(writer, request, "change-password", actor.ID.String(), 5, 12*time.Second) {
		return
	}
	if err := server.identity.ChangePassword(request.Context(), actor, identity.ChangePasswordInput{
		CurrentPassword: body.CurrentPassword, NewPassword: body.NewPassword,
		NewPasswordConfirmation: body.NewPasswordConfirmation,
	}); err != nil {
		server.writeIdentityProblem(writer, request, err, false)
		return
	}
	writeNoContent(writer)
}

func (server *Server) deleteAccount(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		CurrentPassword string `json:"current_password"`
		Confirmed       bool   `json:"confirmed"`
	}
	if !decodeOrProblem(writer, request, &body, 2048) {
		return
	}
	actor, _ := actorFromContext(request.Context())
	if err := server.identity.DeleteAccount(request.Context(), actor, body.CurrentPassword, body.Confirmed); err != nil {
		server.writeIdentityProblem(writer, request, err, false)
		return
	}
	server.generation.Registry().CancelActor(actor)
	server.clearSessionCookie(writer)
	writeNoContent(writer)
}

func (server *Server) writeBootstrapProjection(writer http.ResponseWriter, request *http.Request, actor identity.Actor) {
	csrf, err := server.csrf.Sign(actor.CSRFSubject(), server.identityNow())
	if err != nil {
		writeProblem(writer, request, http.StatusInternalServerError, "internal_error", "Internal error", "The request could not be completed.")
		return
	}
	dto := actorDTO{Kind: actor.Kind}
	if actor.Kind == "account" {
		dto.Username = &actor.Username
		dto.Role = &actor.Role
		dto.PlanCode = identity.PlanCode(actor.GroupCode)
	}
	writeJSON(writer, request, http.StatusOK, bootstrapDTO{
		Actor: dto, UILocale: actor.UILocale,
		SupportedUILocales: []string{"zh-CN", "en-US"}, CSRFToken: csrf,
	})
}

func (server *Server) writeAuthProjection(writer http.ResponseWriter, request *http.Request, status int, actor identity.Actor) {
	csrf, err := server.csrf.Sign(actor.CSRFSubject(), server.identityNow())
	if err != nil {
		writeProblem(writer, request, http.StatusInternalServerError, "internal_error", "Internal error", "The request could not be completed.")
		return
	}
	dto := actorDTO{Kind: actor.Kind}
	if actor.Kind == "account" {
		dto.Username = &actor.Username
		dto.Role = &actor.Role
		dto.PlanCode = identity.PlanCode(actor.GroupCode)
	}
	writeJSON(writer, request, status, authDTO{Actor: dto, UILocale: actor.UILocale, CSRFToken: csrf})
}

func (server *Server) writeIdentityProblem(writer http.ResponseWriter, request *http.Request, err error, registering bool) {
	switch {
	case errors.Is(err, identity.ErrAuthentication):
		writeProblem(writer, request, http.StatusUnauthorized, "invalid_credentials", "Sign in failed", "The username or password is incorrect.")
	case errors.Is(err, identity.ErrUnauthorized):
		writeProblem(writer, request, http.StatusUnauthorized, "authentication_required", "Sign in required", "Authentication is required for this operation.")
	case errors.Is(err, identity.ErrForbidden):
		writeProblem(writer, request, http.StatusForbidden, "forbidden", "Access denied", "This operation is not available for this account.")
	case errors.Is(err, identity.ErrUsernameTaken) && registering:
		writeProblem(writer, request, http.StatusConflict, "username_unavailable", "Username unavailable", "Choose a different username.", fieldError{Field: "username", Code: "unavailable"})
	case errors.Is(err, identity.ErrValidation):
		writeProblem(writer, request, http.StatusUnprocessableEntity, "validation_failed", "Request could not be accepted", "One or more fields need attention.")
	default:
		writeProblem(writer, request, http.StatusInternalServerError, "internal_error", "Internal error", "The request could not be completed.")
	}
}

func (server *Server) identityNow() time.Time { return time.Now() }

func dereference(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

