		},
	}
}

type liveGenerationResult struct {
	Passage     string
	Tags        []string
	Targets     []map[string]any
	Streamed    string
	FirstDelta  time.Duration
	RawTerminal string
	ResultJSON  string
}

func readLiveGenerationSSE(t *testing.T, body io.Reader) liveGenerationResult {
	t.Helper()
	started := time.Now()
	scanner := bufio.NewScanner(body)
	scanner.Buffer(make([]byte, 64<<10), 4<<20)
	var event string
	var streamed strings.Builder
	var firstDelta time.Duration
	var result liveGenerationResult
	foundStarted := false
	foundTerminal := false

	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "event: ") {
			event = strings.TrimPrefix(line, "event: ")
			continue
		}
		if !strings.HasPrefix(line, "data: ") {
			continue
		}
		raw := strings.TrimPrefix(line, "data: ")
		var payload map[string]any
		if err := json.Unmarshal([]byte(raw), &payload); err != nil {
			t.Fatalf("decode SSE %s payload: %v", event, err)
		}
		switch event {
		case "generation.started":
			foundStarted = payload["run_id"] != "" && payload["generation_token"] != ""
		case "passage.delta":
			if firstDelta == 0 {
				firstDelta = time.Since(started)
			}
			text, _ := payload["text"].(string)
			streamed.WriteString(text)
		case "generation.failed":
			t.Fatalf("generation failed: code=%v retryable=%v", payload["code"], payload["retryable"])
		case "generation.cancelled":
			t.Fatal("generation was unexpectedly cancelled")
		case "generation.validated":
			encoded, err := json.Marshal(payload["result"])
			if err != nil {
				t.Fatal(err)
			}
			var terminal struct {
				Passage string           `json:"passage"`
				Tags    []string         `json:"tags"`
				Targets []map[string]any `json:"targets"`
			}
			if err := json.Unmarshal(encoded, &terminal); err != nil {
				t.Fatal(err)
			}
			result.Passage, result.Tags, result.Targets = terminal.Passage, terminal.Tags, terminal.Targets
			result.RawTerminal = raw
			result.ResultJSON = string(encoded)
			foundTerminal = true
		}
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	if !foundStarted || !foundTerminal {
		t.Fatalf("stream missing lifecycle event: started=%v validated=%v", foundStarted, foundTerminal)
	}
	result.Streamed = streamed.String()
	result.FirstDelta = firstDelta
	return result
}

func assertLiveGenerationResult(t *testing.T, result liveGenerationResult, entries []string, minimumWords int) {
	t.Helper()
	if result.Passage == "" || result.Streamed != result.Passage {
		t.Fatalf("streamed passage does not exactly match terminal passage: streamed=%d terminal=%d", len(result.Streamed), len(result.Passage))
	}
	if result.FirstDelta <= 0 {
		t.Fatal("stream did not emit a passage delta before validation")
	}
	if words := ai.CountWords(result.Passage); words < minimumWords {
		t.Fatalf("passage words=%d minimum=%d", words, minimumWords)
	}
	if len(result.Tags) < 1 || len(result.Tags) > 3 || len(result.Targets) != len(entries) {
		t.Fatalf("unexpected result cardinality: tags=%d targets=%d", len(result.Tags), len(result.Targets))
	}
	for index, target := range result.Targets {
		if target["entry"] != entries[index] {
			t.Fatalf("target %d entry=%v want=%s", index, target["entry"], entries[index])
		}
		for _, field := range []string{"entry_meaning", "hint_phrase", "hint_blanks", "occurrences"} {
			if target[field] == nil {
				t.Fatalf("target %d omitted %s", index, field)
			}
		}
		if _, stale := target["hint_blank"]; stale {
			t.Fatalf("target %d exposed stale singular hint_blank", index)
		}
		if _, leaked := target["hint_surface"]; leaked {
			t.Fatalf("target %d leaked hint_surface", index)
		}
	}
	if strings.Contains(result.RawTerminal, "generation_token") || strings.Contains(result.RawTerminal, "provider_model_id") {
		t.Fatal("validated terminal event leaked a capability or provider model ID")
	}
}

func passagePreview(passage string) string {
	const limit = 140
	value := []rune(passage)
	if len(value) <= limit {
		return passage
	}
	return string(value[:limit]) + "…"
}

func newLocalListener(t *testing.T) net.Listener {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	return listener
}

package httpapi

import (
	"encoding/base64"
	"math"
	"net"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"wordweave/internal/platform/security"
)

type tokenBucket struct {
	tokens   float64
	updated  time.Time
	lastUsed time.Time
}

type authRateLimiter struct {
	mutex   sync.Mutex
	key     []byte
	buckets map[string]tokenBucket
	checks  uint64
}

func newAuthRateLimiter(key []byte) *authRateLimiter {
	return &authRateLimiter{key: append([]byte(nil), key...), buckets: make(map[string]tokenBucket)}
}

func (limiter *authRateLimiter) allow(operation, subject, source string, capacity int, refillInterval time.Duration) (bool, int) {
	now := time.Now()
	keyMaterial := operation + "\x00" + strings.ToLower(strings.TrimSpace(subject)) + "\x00" + source
	key := base64.RawURLEncoding.EncodeToString(security.Digest(limiter.key, "auth-rate-v1", keyMaterial))
	limiter.mutex.Lock()
	defer limiter.mutex.Unlock()
	limiter.checks++
	if limiter.checks%512 == 0 {
		for existingKey, bucket := range limiter.buckets {
			if now.Sub(bucket.lastUsed) > 24*time.Hour {
				delete(limiter.buckets, existingKey)
			}
		}
	}
	bucket, found := limiter.buckets[key]
	if !found {
		bucket = tokenBucket{tokens: float64(capacity), updated: now}
	}
	refillPerSecond := 1 / refillInterval.Seconds()
	bucket.tokens = math.Min(float64(capacity), bucket.tokens+now.Sub(bucket.updated).Seconds()*refillPerSecond)
	bucket.updated, bucket.lastUsed = now, now
	if bucket.tokens < 1 {
		limiter.buckets[key] = bucket
		retryAfter := int(math.Ceil((1 - bucket.tokens) / refillPerSecond))
		if retryAfter < 1 {
			retryAfter = 1
		}
		return false, retryAfter
	}
	bucket.tokens--
	limiter.buckets[key] = bucket
	return true, 0
}

func (server *Server) requireAuthRate(writer http.ResponseWriter, request *http.Request, operation, subject string, capacity int, refillInterval time.Duration) bool {
	allowed, retryAfter := server.authLimiter.allow(operation, subject, server.coarseRequestSource(request), capacity, refillInterval)
	if allowed {
		return true
	}
	writer.Header().Set("Retry-After", strconv.Itoa(retryAfter))
	writeProblem(writer, request, http.StatusTooManyRequests, "rate_limited", "Too many attempts", "Wait before trying this operation again.")
	return false
}

func (server *Server) coarseRequestSource(request *http.Request) string {
	remote := parseRemoteIP(request.RemoteAddr)
	client := remote
	if server.isTrustedProxy(remote) {
		chain := strings.Split(request.Header.Get("X-Forwarded-For"), ",")
		for index := len(chain) - 1; index >= 0; index-- {
			candidate := net.ParseIP(strings.TrimSpace(chain[index]))
			if candidate == nil {
				continue
			}
			client = candidate
			if !server.isTrustedProxy(candidate) {
				break
			}
		}
	}
	if client == nil {
		return "unknown"
	}
	return coarseIP(client)
}

func (server *Server) isTrustedProxy(ip net.IP) bool {
	if ip == nil {
		return false
	}
	for _, network := range server.cfg.TrustedProxyCIDRs {
		if network.Contains(ip) {
			return true
		}
	}
	return false
}

func coarseSource(remoteAddress string) string {
	ip := parseRemoteIP(remoteAddress)
	if ip == nil {
		return "unknown"
	}
	return coarseIP(ip)
}

func parseRemoteIP(remoteAddress string) net.IP {
	host, _, err := net.SplitHostPort(remoteAddress)
	if err != nil {
		host = remoteAddress
	}
	return net.ParseIP(strings.Trim(host, "[]"))
}

func coarseIP(ip net.IP) string {
	if ipv4 := ip.To4(); ipv4 != nil {
		return ipv4.Mask(net.CIDRMask(24, 32)).String() + "/24"
	}
	return ip.Mask(net.CIDRMask(64, 128)).String() + "/64"
}

package httpapi

import (
	"net"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"wordweave/internal/platform/config"
)

func TestAuthRateLimiterSeparatesOperationSubjectAndSource(t *testing.T) {
	limiter := newAuthRateLimiter([]byte(strings.Repeat("r", 32)))
	for index := 0; index < 2; index++ {
		if allowed, _ := limiter.allow("login", "Reader", "192.0.2.0/24", 2, time.Hour); !allowed {
			t.Fatal("request inside capacity was rejected")
		}
	}
	if allowed, retry := limiter.allow("login", "reader", "192.0.2.0/24", 2, time.Hour); allowed || retry < 1 {
		t.Fatalf("exhausted bucket allowed=%v retry=%d", allowed, retry)
	}
	if allowed, _ := limiter.allow("register", "reader", "192.0.2.0/24", 2, time.Hour); !allowed {
		t.Fatal("another operation unexpectedly shared the bucket")
	}
	if allowed, _ := limiter.allow("login", "reader", "198.51.100.0/24", 2, time.Hour); !allowed {
		t.Fatal("another source unexpectedly shared the bucket")
	}
}

func TestCoarseSourceDoesNotRetainHostAddress(t *testing.T) {
	if got := coarseSource("192.0.2.123:443"); got != "192.0.2.0/24" {
		t.Fatalf("IPv4 coarse source = %q", got)
	}
	if got := coarseSource("[2001:db8:abcd:1234:5678::1]:443"); got != "2001:db8:abcd:1234::/64" {
		t.Fatalf("IPv6 coarse source = %q", got)
	}
}

func TestTrustedProxyUsesRightmostUntrustedForwardedAddress(t *testing.T) {
	_, trusted, _ := net.ParseCIDR("10.0.0.0/8")
	server := &Server{cfg: config.Config{TrustedProxyCIDRs: []*net.IPNet{trusted}}}
	request := httptest.NewRequest("POST", "/", nil)
	request.RemoteAddr = "10.0.0.2:443"
	request.Header.Set("X-Forwarded-For", "192.0.2.123, 10.0.0.3")
	if got := server.coarseRequestSource(request); got != "192.0.2.0/24" {
		t.Fatalf("trusted proxy source = %q", got)
	}
	request.RemoteAddr = "198.51.100.12:443"
	if got := server.coarseRequestSource(request); got != "198.51.100.0/24" {
		t.Fatalf("untrusted proxy header affected source: %q", got)
	}
}

