		response := rawJSONRequest(t, learnerClient, http.MethodDelete, application.URL+"/api/v1/me/batches/"+batchID, learnerCSRF, nil, nil)
		assertPrivateNoContentResponse(t, response)

		var remaining int
		if err := pool.QueryRow(ctx, `SELECT count(*) FROM wordweave.review_sessions WHERE id=$1`, sessionID).Scan(&remaining); err != nil {
			t.Fatal(err)
		}
		if remaining != 0 {
			t.Fatalf("review session %s remains after batch deletion", sessionID)
		}
	})

	var learnerID uuid.UUID
	if err := pool.QueryRow(ctx, `SELECT id FROM wordweave.accounts WHERE lower(username)='cr038_learner'`).Scan(&learnerID); err != nil {
		t.Fatal(err)
	}
	t.Run("administrator password reset", func(t *testing.T) {
		response := rawJSONRequest(t, adminClient, http.MethodPut, application.URL+"/api/v1/admin/users/"+learnerID.String()+"/password", adminCSRF, map[string]any{
			"new_password": "cr038-admin-reset-password-789", "new_password_confirmation": "cr038-admin-reset-password-789", "confirmed": true,
		}, nil)
		assertPrivateNoContentResponse(t, response)
	})

	deleteClient := newBrowserClient(t)
	deleteCSRF := bootstrap(t, deleteClient, application.URL)
	deleteRegistration := postJSON(t, deleteClient, application.URL+"/api/v1/auth/register", deleteCSRF, map[string]any{
		"username": "cr038_delete", "password": "cr038-delete-password-123",
		"password_confirmation": "cr038-delete-password-123", "ui_locale": "en-US",
	})
	requireStatus(t, deleteRegistration, http.StatusCreated)
	deleteCSRF = dataString(t, deleteRegistration.body, "csrf_token")
	t.Run("account deletion", func(t *testing.T) {
		response := rawJSONRequest(t, deleteClient, http.MethodDelete, application.URL+"/api/v1/me/account", deleteCSRF, map[string]any{
			"current_password": "cr038-delete-password-123", "confirmed": true,
		}, nil)
		assertPrivateNoContentResponse(t, response)

		var remaining int
		if err := pool.QueryRow(ctx, `SELECT count(*) FROM wordweave.accounts WHERE lower(username)='cr038_delete'`).Scan(&remaining); err != nil {
			t.Fatal(err)
		}
		if remaining != 0 {
			t.Fatal("deleted synthetic account still exists")
		}
	})
}

func assertPrivateNoContentResponse(t *testing.T, response *http.Response) {
	t.Helper()
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	if response.StatusCode != http.StatusNoContent {
		t.Fatalf("status=%d, want=%d body=%q", response.StatusCode, http.StatusNoContent, body)
	}
	if len(body) != 0 {
		t.Fatalf("body length=%d, want=0 body=%q", len(body), body)
	}
	if contentType := response.Header.Get("Content-Type"); contentType != "" {
		t.Fatalf("Content-Type=%q, want absent", contentType)
	}
	if cacheControl := response.Header.Get("Cache-Control"); cacheControl != "no-store" {
		t.Fatalf("Cache-Control=%q, want=no-store", cacheControl)
	}
}

package httpapi

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestWriteNoContentEnforcesPrivateNoStoreResponse(t *testing.T) {
	t.Parallel()

	for _, test := range []struct {
		name              string
		presetContentType string
		presetCache       string
	}{
		{name: "empty headers"},
		{name: "removes preset content type", presetContentType: "application/json; charset=utf-8"},
		{name: "overrides preset cache policy", presetCache: "private, max-age=60"},
		{name: "removes content type and overrides cache policy", presetContentType: "text/plain", presetCache: "public, max-age=3600"},
	} {
		test := test
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			writer := httptest.NewRecorder()
			if test.presetContentType != "" {
				writer.Header().Set("Content-Type", test.presetContentType)
			}
			if test.presetCache != "" {
				writer.Header().Set("Cache-Control", test.presetCache)
			}

			writeNoContent(writer)
			response := writer.Result()
			defer response.Body.Close()

			if response.StatusCode != http.StatusNoContent {
				t.Fatalf("status = %d, want %d", response.StatusCode, http.StatusNoContent)
			}
			if body := writer.Body.Bytes(); len(body) != 0 {
				t.Fatalf("body length = %d, want 0; body = %q", len(body), body)
			}
			if contentType := response.Header.Get("Content-Type"); contentType != "" {
				t.Fatalf("Content-Type = %q, want absent", contentType)
			}
			if cacheControl := response.Header.Get("Cache-Control"); cacheControl != "no-store" {
				t.Fatalf("Cache-Control = %q, want %q", cacheControl, "no-store")
			}
		})
	}
}

func TestSuccessEnvelopeSeparatesOrdinaryAndListMetadata(t *testing.T) {
	t.Parallel()

	request := httptest.NewRequest("GET", "/", nil)
	request = request.WithContext(context.WithValue(request.Context(), requestIDKey, "req_test"))

	t.Run("ordinary response omits pagination fields", func(t *testing.T) {
		writer := httptest.NewRecorder()
		writeJSON(writer, request, 200, struct{}{})

		meta := responseMetadata(t, writer.Body.Bytes())
		if _, exists := meta["next_cursor"]; exists {
			t.Fatalf("ordinary response unexpectedly included next_cursor: %s", writer.Body.String())
		}
		if _, exists := meta["has_more"]; exists {
			t.Fatalf("ordinary response unexpectedly included has_more: %s", writer.Body.String())
		}
	})

	t.Run("terminal list explicitly includes null cursor and false has_more", func(t *testing.T) {
		writer := httptest.NewRecorder()
		writeListJSON(writer, request, struct {
			Items []string `json:"items"`
		}{Items: []string{}}, nil, false)

		meta := responseMetadata(t, writer.Body.Bytes())
		nextCursor, exists := meta["next_cursor"]
		if !exists || nextCursor != nil {
			t.Fatalf("terminal list next_cursor = %#v, exists = %t; response = %s", nextCursor, exists, writer.Body.String())
		}
		hasMore, exists := meta["has_more"]
		if !exists || hasMore != false {
			t.Fatalf("terminal list has_more = %#v, exists = %t; response = %s", hasMore, exists, writer.Body.String())
		}
	})

	t.Run("non-terminal list includes opaque cursor and true has_more", func(t *testing.T) {
		writer := httptest.NewRecorder()
		cursor := "cur_test"
		writeListJSON(writer, request, struct {
			Items []string `json:"items"`
		}{Items: []string{"one"}}, &cursor, true)

		meta := responseMetadata(t, writer.Body.Bytes())
		if meta["next_cursor"] != cursor || meta["has_more"] != true {
			t.Fatalf("non-terminal list metadata mismatch: %s", writer.Body.String())
		}
	})
}

func responseMetadata(t *testing.T, raw []byte) map[string]any {
	t.Helper()
	var envelope struct {
		Meta map[string]any `json:"meta"`
	}
	if err := json.Unmarshal(raw, &envelope); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	return envelope.Meta
}

func TestDecodeStrictRejectsUnknownDuplicateAndMultipleValues(t *testing.T) {
	t.Parallel()
	for _, raw := range []string{`{"name":"a","name":"b"}`, `{"unknown":true}`, `{"name":"a"} {}`} {
		request := httptest.NewRequest("POST", "/", strings.NewReader(raw))
		writer := httptest.NewRecorder()
		var target struct {
			Name string `json:"name"`
		}
		if err := decodeStrict(writer, request, &target, 1024); err == nil {
			t.Fatalf("decodeStrict(%q) unexpectedly succeeded", raw)
		}
	}
}

func TestDecodeStrictAcceptsSingleKnownObject(t *testing.T) {
	t.Parallel()
	request := httptest.NewRequest("POST", "/", strings.NewReader(`{"name":"WordWeave"}`))
	writer := httptest.NewRecorder()
	var target struct {
		Name string `json:"name"`
	}
	if err := decodeStrict(writer, request, &target, 1024); err != nil {
		t.Fatal(err)
	}
	if target.Name != "WordWeave" {
		t.Fatalf("name = %q", target.Name)
	}
}

package httpapi

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/google/uuid"

	"wordweave/internal/review"
)

func (server *Server) reviewRangePreview(writer http.ResponseWriter, request *http.Request) {
	actor, _ := actorFromContext(request.Context())
	preview, err := server.review.Preview(
		request.Context(), actor.ID, request.URL.Query().Get("start_date"),
		request.URL.Query().Get("end_date"), request.URL.Query().Get("timezone"),
	)
	if err != nil {
		server.writeReviewProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, struct {
		BatchCount int  `json:"batch_count"`
		EntryCount int  `json:"entry_count"`
		Empty      bool `json:"empty"`
	}{BatchCount: preview.BatchCount, EntryCount: preview.EntryCount, Empty: preview.BatchCount == 0 && preview.EntryCount == 0})
}

func (server *Server) activeRangeSession(writer http.ResponseWriter, request *http.Request) {
	actor, _ := actorFromContext(request.Context())
	session, err := server.review.ActiveRange(request.Context(), actor.ID)
	if err != nil {
		server.writeReviewProblem(writer, request, err)
		return
	}
	if session == nil {
		writeJSON(writer, request, http.StatusOK, struct {
			Session any `json:"session"`
		}{Session: nil})
		return
	}
	writeJSON(writer, request, http.StatusOK, struct {
		Session activeRangeDTO `json:"session"`
	}{Session: mapActiveRange(*session)})
}

func (server *Server) createReviewSession(writer http.ResponseWriter, request *http.Request) {
	var body struct {
		Mode      string         `json:"mode"`
		StartDate optionalString `json:"start_date"`
		EndDate   optionalString `json:"end_date"`
		Timezone  optionalString `json:"timezone"`
		BatchID   optionalString `json:"batch_id"`
	}
	if !decodeOrProblem(writer, request, &body, 2048) {
		return
	}
	input := review.CreateInput{Mode: body.Mode}
	if body.Mode == "range" {
		if !body.StartDate.Set || body.StartDate.Value == nil || !body.EndDate.Set || body.EndDate.Value == nil ||
			!body.Timezone.Set || body.Timezone.Value == nil || body.BatchID.Set {
			server.writeReviewProblem(writer, request, review.ErrValidation)
			return
		}
		input.StartDate, input.EndDate, input.Timezone = *body.StartDate.Value, *body.EndDate.Value, *body.Timezone.Value
	} else if body.Mode == "single_batch" {
		if !body.BatchID.Set || body.BatchID.Value == nil || body.StartDate.Set || body.EndDate.Set || body.Timezone.Set {
			server.writeReviewProblem(writer, request, review.ErrValidation)
			return
		}
		batchID, err := uuid.Parse(*body.BatchID.Value)
		if err != nil {
			server.writeReviewProblem(writer, request, review.ErrValidation)
			return
		}
		input.BatchID = batchID
	} else {
		server.writeReviewProblem(writer, request, review.ErrValidation)
		return
	}
	actor, _ := actorFromContext(request.Context())
	session, err := server.review.Create(request.Context(), actor.ID, input)
	if err != nil {
		server.writeReviewProblem(writer, request, err)
		return
	}
	status := http.StatusCreated
	if session.Reused {
		status = http.StatusOK
	}
	writeJSON(writer, request, status, mapReviewCreation(session))
}

func (server *Server) getReviewSession(writer http.ResponseWriter, request *http.Request) {
	actor, _ := actorFromContext(request.Context())
	sessionID, err := uuid.Parse(chi.URLParam(request, "session_id"))
	if err != nil {
		server.writeReviewProblem(writer, request, review.ErrNotFound)
		return
	}
	session, err := server.review.GetSession(request.Context(), actor.ID, sessionID)
	if err != nil {
		server.writeReviewProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, struct {
		Session reviewSessionDTO `json:"session"`
	}{Session: mapReviewSession(session)})
}

func (server *Server) startReviewAttempt(writer http.ResponseWriter, request *http.Request) {
	var body struct{}
	if !decodeOrProblem(writer, request, &body, 128) {
		return
	}
	sessionID, err := uuid.Parse(chi.URLParam(request, "session_id"))
	if err != nil {
		server.writeReviewProblem(writer, request, review.ErrNotFound)
		return
	}
	actor, _ := actorFromContext(request.Context())
	attempt, err := server.review.StartAttempt(request.Context(), actor, sessionID)
	if err != nil {
		server.writeReviewProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusCreated, struct {
		AttemptID    string                `json:"attempt_id"`
		AttemptToken string                `json:"attempt_token"`
		Item         map[string]any        `json:"item"`
		Progress     reviewItemProgressDTO `json:"progress"`
	}{
		AttemptID: attempt.ID, AttemptToken: attempt.Token,
		Item: mapReviewItem(attempt.Item), Progress: mapReviewItemProgress(attempt.Progress),
	})
}

func (server *Server) reviewAction(writer http.ResponseWriter, request *http.Request) {
	var body reviewActionRequest
	if !decodeOrProblem(writer, request, &body, 64<<10) {
		return
	}
	if body.Action == "skip" && (body.Answer.Set || body.Answers.Set) ||
		body.Action == "answer" && body.Answer.Set == body.Answers.Set ||
		(body.Action != "skip" && body.Action != "answer") {
		server.writeReviewProblem(writer, request, review.ErrValidation)
		return
	}
	if body.Answer.Set && body.Answer.Value == nil {
		server.writeReviewProblem(writer, request, review.ErrValidation)
		return
	}
	answers := []review.BlankAnswer(nil)
	if body.Answers.Set {
		answers = make([]review.BlankAnswer, 0, len(body.Answers.Values))
		for _, answer := range body.Answers.Values {
			answers = append(answers, review.BlankAnswer{BlankID: answer.BlankID, Answer: answer.Answer})
		}
	}
	var answer *string
	if body.Answer.Set {
		answer = body.Answer.Value
	}
	actor, _ := actorFromContext(request.Context())
	outcome, err := server.review.Act(request.Context(), actor, chi.URLParam(request, "attempt_id"), request.Header.Get("X-Review-Attempt-Token"), review.Action{
		ActionID: body.ActionID, ItemID: body.ItemID, Kind: body.Action,
		Answer: answer, Answers: answers,
	})
	if err != nil {
		server.writeReviewProblem(writer, request, err)
		return
	}
	writeJSON(writer, request, http.StatusOK, mapReviewOutcome(outcome))
}

type reviewAnswerDTO struct {
	BlankID string `json:"blank_id"`
	Answer  string `json:"answer"`
}

type reviewActionRequest struct {
	ActionID string          `json:"action_id"`
	ItemID   string          `json:"item_id"`
	Action   string          `json:"action"`
	Answer   optionalString  `json:"answer"`
	Answers  optionalAnswers `json:"answers"`
}

type optionalAnswers struct {
	Set    bool
	Values []reviewAnswerDTO
}

func (value *optionalAnswers) UnmarshalJSON(raw []byte) error {
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return errors.New("answers cannot be null")
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	var answers []reviewAnswerDTO
	if err := decoder.Decode(&answers); err != nil {
		return err
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		return errors.New("answers must contain one JSON value")
	}
	value.Values = answers
	value.Set = true
	return nil
}

type progressDTO struct {
	CompletedBatches    int `json:"completed_batches"`
	TotalBatches        int `json:"total_batches"`
	SuccessfulBatches   int `json:"successful_batches"`
	UnsuccessfulBatches int `json:"unsuccessful_batches"`
}

type dateRangeDTO struct {
	StartDate string `json:"start_date"`
	EndDate   string `json:"end_date"`
	Timezone  string `json:"timezone"`
}

type batchProjectionDTO struct {
	BatchID  string `json:"batch_id"`
	SavedAt  string `json:"saved_at"`
	Scenario string `json:"scenario"`
}

type summaryDTO struct {
	TotalBatches        int `json:"total_batches"`
	SuccessfulBatches   int `json:"successful_batches"`
	UnsuccessfulBatches int `json:"unsuccessful_batches"`
	SkippedBatches      int `json:"skipped_batches"`
}

type activeRangeDTO struct {
	SessionID string       `json:"session_id"`
	Mode      string       `json:"mode"`
	Status    string       `json:"status"`
	DateRange dateRangeDTO `json:"date_range"`
	Progress  progressDTO  `json:"progress"`
}

type reviewSessionDTO struct {
	SessionID    string              `json:"session_id"`
	Mode         string              `json:"mode"`
	Status       string              `json:"status"`
	DateRange    *dateRangeDTO       `json:"date_range"`
	Progress     progressDTO         `json:"progress"`
	CurrentBatch *batchProjectionDTO `json:"current_batch"`
	Summary      *summaryDTO         `json:"summary"`
}

type reviewCreationDTO struct {
	SessionID    string              `json:"session_id"`
	Mode         string              `json:"mode"`
	Status       string              `json:"status"`
	Reused       bool                `json:"reused"`
	DateRange    *dateRangeDTO       `json:"date_range"`
	Progress     progressDTO         `json:"progress"`
	CurrentBatch *batchProjectionDTO `json:"current_batch"`
}

type reviewItemProgressDTO struct {
	Stage        string `json:"stage"`
	ItemNumber   int    `json:"item_number"`
	ItemsInStage int    `json:"items_in_stage"`
}

func mapActiveRange(session review.Session) activeRangeDTO {
	return activeRangeDTO{
		SessionID: session.ID.String(), Mode: "range", Status: "active",
		DateRange: mapDateRange(*session.DateRange), Progress: mapReviewProgress(session.Progress),
	}
}

func mapReviewCreation(session review.Session) reviewCreationDTO {
	dto := reviewCreationDTO{
		SessionID: session.ID.String(), Mode: session.Mode, Status: session.Status,
		Reused: session.Reused, Progress: mapReviewProgress(session.Progress),
	}
	if session.DateRange != nil {
		value := mapDateRange(*session.DateRange)
		dto.DateRange = &value
	}
	if session.CurrentBatch != nil {
		value := mapBatchProjection(*session.CurrentBatch)
		dto.CurrentBatch = &value
	}
	return dto
}

func mapReviewSession(session review.Session) reviewSessionDTO {
	dto := reviewSessionDTO{
		SessionID: session.ID.String(), Mode: session.Mode, Status: session.Status,
		Progress: mapReviewProgress(session.Progress),
	}
	if session.DateRange != nil {
		value := mapDateRange(*session.DateRange)
		dto.DateRange = &value
	}
	if session.CurrentBatch != nil {
		value := mapBatchProjection(*session.CurrentBatch)
		dto.CurrentBatch = &value
	}
	if session.Summary != nil {
		value := mapSummary(*session.Summary)
		dto.Summary = &value
	}
	return dto
}

func mapReviewItem(item review.Item) map[string]any {
	if item.Stage == "spelling" {
		segments := make([]any, 0, len(item.HintSegments))
		for _, segment := range item.HintSegments {
			if segment.Kind == "text" {
				segments = append(segments, map[string]any{"kind": "text", "text": segment.Text})
			} else {
				segments = append(segments, map[string]any{"kind": "blank", "length_hint": segment.LengthHint})
			}
		}
		return map[string]any{
			"stage": "spelling", "item_id": item.ID, "entry_meaning": item.EntryMeaning,
			"hint": map[string]any{"segments": segments},
		}
	}
	segments := make([]any, 0, len(item.PassageSegments))
	for _, segment := range item.PassageSegments {
		if segment.Kind == "text" {
			segments = append(segments, map[string]any{"kind": "text", "text": segment.Text})
		} else {
			segments = append(segments, map[string]any{"kind": "blank", "blank_id": segment.BlankID, "group_key": segment.GroupKey})
		}
	}
	return map[string]any{"stage": "passage_cloze", "item_id": item.ID, "passage_segments": segments}
}

func mapReviewOutcome(outcome review.Outcome) any {
	switch outcome.Kind {
	case "retry":
		var incorrect any
		if outcome.Item != nil && outcome.Item.Stage == "passage_cloze" {
			incorrect = outcome.IncorrectBlankIDs
		}
		return struct {
			Outcome           string                `json:"outcome"`
			Result            string                `json:"result"`
			Item              map[string]any        `json:"item"`
			Progress          reviewItemProgressDTO `json:"progress"`
			IncorrectBlankIDs any                   `json:"incorrect_blank_ids"`
		}{"retry", "incorrect", mapReviewItem(*outcome.Item), mapReviewItemProgress(*outcome.Progress), incorrect}
	case "advanced":
		return struct {
			Outcome  string                `json:"outcome"`
			Result   string                `json:"result"`
			Item     map[string]any        `json:"item"`
			Progress reviewItemProgressDTO `json:"progress"`
		}{"advanced", outcome.Result, mapReviewItem(*outcome.Item), mapReviewItemProgress(*outcome.Progress)}
	case "batch_completed":
		return struct {
			Outcome         string             `json:"outcome"`
			BatchResult     batchResultDTO     `json:"batch_result"`
			SessionProgress progressDTO        `json:"session_progress"`
			NextBatch       batchProjectionDTO `json:"next_batch"`
		}{"batch_completed", mapBatchResult(*outcome.BatchResult), mapReviewProgress(*outcome.SessionProgress), mapBatchProjection(*outcome.NextBatch)}
	default:
		return struct {
			Outcome         string         `json:"outcome"`
			BatchResult     batchResultDTO `json:"batch_result"`
			SessionProgress progressDTO    `json:"session_progress"`
			NextBatch       any            `json:"next_batch"`
			SessionSummary  summaryDTO     `json:"session_summary"`
		}{"session_completed", mapBatchResult(*outcome.BatchResult), mapReviewProgress(*outcome.SessionProgress), nil, mapSummary(*outcome.SessionSummary)}
	}
}

type batchResultDTO struct {
	BatchID    string `json:"batch_id"`
	Successful bool   `json:"successful"`
	ErrorCount int    `json:"error_count"`
	SkipCount  int    `json:"skip_count"`
}

func mapBatchResult(result review.BatchResult) batchResultDTO {
	return batchResultDTO{BatchID: result.BatchID.String(), Successful: result.Successful, ErrorCount: result.ErrorCount, SkipCount: result.SkipCount}
}

func mapReviewProgress(progress review.Progress) progressDTO {
	return progressDTO{progress.Completed, progress.Total, progress.Successful, progress.Unsuccessful}
}

func mapReviewItemProgress(progress review.ItemProgress) reviewItemProgressDTO {
	return reviewItemProgressDTO{Stage: progress.Stage, ItemNumber: progress.ItemNumber, ItemsInStage: progress.ItemsInStage}
}

func mapDateRange(value review.DateRange) dateRangeDTO {
	return dateRangeDTO{StartDate: value.StartDate, EndDate: value.EndDate, Timezone: value.Timezone}
}

func mapBatchProjection(value review.BatchProjection) batchProjectionDTO {
	return batchProjectionDTO{BatchID: value.ID.String(), SavedAt: value.SavedAt.Format(time.RFC3339Nano), Scenario: value.Scenario}
}

func mapSummary(value review.Summary) summaryDTO {
	return summaryDTO{TotalBatches: value.Total, SuccessfulBatches: value.Successful, UnsuccessfulBatches: value.Unsuccessful, SkippedBatches: value.Skipped}
}

func (server *Server) writeReviewProblem(writer http.ResponseWriter, request *http.Request, err error) {
	switch {
	case errors.Is(err, review.ErrNotFound):
		writeProblem(writer, request, http.StatusNotFound, "not_found", "Not found", "The review resource could not be found.")
	case errors.Is(err, review.ErrAttemptExpired):
		writeProblem(writer, request, http.StatusGone, "capability_expired", "Review expired", "Start the current batch again.")
	case errors.Is(err, review.ErrConflict), errors.Is(err, review.ErrIncorrectAction):
		writeProblem(writer, request, http.StatusConflict, "conflict", "Review state changed", "Reload the current review state and try again.")
	case errors.Is(err, review.ErrEmpty):
		writeProblem(writer, request, http.StatusUnprocessableEntity, "validation_failed", "Nothing to review", "No saved batches match this review selection.")
	case errors.Is(err, review.ErrValidation):
		writeProblem(writer, request, http.StatusUnprocessableEntity, "validation_failed", "Request could not be accepted", "One or more review fields are invalid.")
	default:
		writeProblem(writer, request, http.StatusInternalServerError, "internal_error", "Internal error", "The request could not be completed.")
	}
}

package httpapi

import (
	"context"
	"net/http"
	"sync/atomic"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"wordweave/internal/admin"
	"wordweave/internal/ai"
	"wordweave/internal/entitlement"
	"wordweave/internal/generation"
	"wordweave/internal/identity"
	"wordweave/internal/learning"
	"wordweave/internal/maintenance"
	"wordweave/internal/observability"
	"wordweave/internal/platform/config"
	"wordweave/internal/platform/security"
	"wordweave/internal/review"
	"wordweave/internal/vocabulary"
)

type Server struct {
	cfg            config.Config
	pool           *pgxpool.Pool
	identity       *identity.Service
	vocabulary     *vocabulary.Service
	entitlement    *entitlement.Service
	credentials    *ai.CredentialStore
	openrouter     *ai.OpenRouter
	generation     *generation.Service
	failureCapture failureCapture
	learning       *learning.Service
	review         *review.Service
	admin          *admin.Service
	maintenance    *maintenance.Runner
	metrics        *observability.Metrics
	authLimiter    *authRateLimiter
	readyState     atomic.Bool
	csrf           security.CSRFSigner
	cursor         security.CursorSigner
}

func New(cfg config.Config, pool, aiPool *pgxpool.Pool) (*Server, error) {
	lexicon, err := ai.LoadEmbeddedLexicon()
	if err != nil {
		return nil, err
	}
	validator := ai.NewValidator(lexicon)
	envelope, err := security.NewEnvelope(cfg.MasterKeys, cfg.CurrentKey)
	if err != nil {
		return nil, err
	}
	credentials := ai.NewCredentialStore(aiPool, envelope)
	openrouter := ai.NewOpenRouter(cfg.OpenRouterBaseURL, cfg.PublicOrigin, credentials, validator)
	generationService := generation.NewService(pool, credentials, openrouter, cfg.CapabilityKey, cfg.DraftTTL, validator)
	learningService := learning.NewService(pool, generationService.Registry(), cfg.CapabilityKey, cfg.DraftTTL, cfg.ClaimTTL)
	reviewService := review.NewService(pool, cfg.CapabilityKey, cfg.AttemptTTL)
	metrics := observability.NewMetrics()
	server := &Server{
		cfg: cfg, pool: pool,
		identity:    identity.NewService(pool, cfg.SessionPepper),
		vocabulary:  vocabulary.NewService(pool),
		entitlement: entitlement.NewService(pool, aiPool),
		credentials: credentials,
		openrouter:  openrouter,
		generation:  generationService,
		learning:    learningService,
		review:      reviewService,
		admin:       admin.NewService(pool, credentials, openrouter, learningService),
		metrics:     metrics,
		authLimiter: newAuthRateLimiter(cfg.CSRFKey),
		csrf:        security.NewCSRFSigner(cfg.CSRFKey, 2*time.Hour),
		cursor:      security.NewCursorSigner(cfg.CursorKey),
	}
	server.maintenance = maintenance.New(pool, generationService, reviewService)
	server.failureCapture, err = newFailureCapture(cfg.PublicOrigin)
	if err != nil {
		return nil, err
	}
	return server, nil
}

func (server *Server) SetReady(ready bool) { server.readyState.Store(ready) }

func (server *Server) RunMaintenance(ctx context.Context) { server.maintenance.Run(ctx) }

func (server *Server) Stop(ctx context.Context) error {
	if server.failureCapture != nil {
		server.failureCapture.Close()
	}
	return server.maintenance.Stop(ctx)
}

func (server *Server) MetricsHandler() http.Handler {
	mux := http.NewServeMux()
	mux.Handle("GET /internal/metrics", server.metrics.Handler(server.pool))
	return mux
}

func (server *Server) Handler() http.Handler {
	router := chi.NewRouter()
	router.Use(server.requestContext, server.recoverPanic, server.securityHeaders)
	router.NotFound(func(writer http.ResponseWriter, request *http.Request) {
		writeProblem(writer, request, http.StatusNotFound, "not_found", "Not found", "The requested resource could not be found.")
	})
	router.MethodNotAllowed(func(writer http.ResponseWriter, request *http.Request) {
		writeProblem(writer, request, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed", "This method is not available for the requested resource.")
	})

	router.Get("/health/live", server.live)
	router.Get("/health/ready", server.ready)

	router.Route("/api/v1", func(api chi.Router) {
		api.Use(server.resolveActor)
		api.Get("/bootstrap", server.bootstrap)
		api.Get("/vocabulary/search", server.vocabularySearch)
		api.Get("/generation-options", server.generationOptions)

		api.Group(func(writes chi.Router) {
			writes.Use(server.requireSafeWrite)
			writes.Post("/auth/register", server.register)
			writes.Post("/auth/login", server.login)
			writes.Post("/auth/logout", server.logout)
			writes.Post("/generations/stream", server.generationStream)
			writes.Post("/generations/{run_id}/cancel", server.cancelGeneration)
			writes.With(requireLearner).Post("/generations/{run_id}/save", server.saveGeneration)
			writes.Post("/generations/{run_id}/discard", server.discardGeneration)
			writes.Post("/generations/{run_id}/visitor-claim", server.createVisitorClaim)
			writes.With(requireLearner).Post("/visitor-claims/consume", server.consumeVisitorClaim)
			writes.With(requireLearner).Patch("/me/batches/{batch_id}", server.patchBatch)
			writes.With(requireLearner).Delete("/me/batches/{batch_id}", server.deleteBatch)
			writes.With(requireLearner).Post("/me/review-sessions", server.createReviewSession)
			writes.With(requireLearner).Post("/me/review-sessions/{session_id}/attempts", server.startReviewAttempt)
			writes.With(requireLearner).Post("/me/review-attempts/{attempt_id}/actions", server.reviewAction)
			writes.Put("/me/ui-locale", server.updateLocale)
			writes.With(requireLearner).Put("/me/password", server.changePassword)
			writes.With(requireLearner).Delete("/me/account", server.deleteAccount)
		})

		api.With(requireLearner).Get("/me/account", server.account)
		api.With(requireLearner).Get("/me/learning-summary", server.learningSummary)
		api.With(requireLearner).Get("/me/batches", server.listBatches)
		api.With(requireLearner).Get("/me/batches/{batch_id}", server.getBatch)
		api.With(requireLearner).Get("/me/review-range/preview", server.reviewRangePreview)
		api.With(requireLearner).Get("/me/review-sessions/active-range", server.activeRangeSession)
		api.With(requireLearner).Get("/me/review-sessions/{session_id}", server.getReviewSession)

		api.Route("/admin", func(admin chi.Router) {
			admin.Use(requireAdmin)
			admin.Get("/openrouter-credential", server.adminCredential)
			admin.Get("/models", server.adminListModels)
			admin.Get("/groups", server.adminListGroups)
			admin.Get("/users", server.adminListUsers)
			admin.Get("/users/{user_id}", server.adminGetUser)
			admin.Get("/users/{user_id}/batches", server.adminListUserBatches)
			admin.Get("/users/{user_id}/batches/{batch_id}", server.adminGetUserBatch)

			admin.Group(func(writes chi.Router) {
				writes.Use(server.requireSafeWrite)
				writes.Put("/openrouter-credential", server.adminPutCredential)
				writes.Post("/models", server.adminCreateModel)
				writes.Patch("/models/{model_id}", server.adminPatchModel)
				writes.Post("/models/{model_id}/enable", server.adminEnableModel)
				writes.Post("/models/{model_id}/disable", server.adminDisableModel)
				writes.Put("/groups/{group_code}", server.adminPutGroup)
				writes.Put("/users/{user_id}/group", server.adminChangeUserGroup)
				writes.Put("/users/{user_id}/password", server.adminResetUserPassword)
			})
		})
	})
	return router
}

func (server *Server) live(writer http.ResponseWriter, _ *http.Request) {
	writer.Header().Set("Content-Type", "text/plain; charset=utf-8")
	writer.WriteHeader(http.StatusOK)
	_, _ = writer.Write([]byte("ok\n"))
}

func (server *Server) ready(writer http.ResponseWriter, request *http.Request) {
	if !server.readyState.Load() {
		http.Error(writer, "not ready", http.StatusServiceUnavailable)
		return
	}
	ctx, cancel := context.WithTimeout(request.Context(), 2*time.Second)
	defer cancel()
	if err := server.pool.Ping(ctx); err != nil {
		http.Error(writer, "not ready", http.StatusServiceUnavailable)
		return
	}
	writer.Header().Set("Content-Type", "text/plain; charset=utf-8")
	writer.WriteHeader(http.StatusOK)
	_, _ = writer.Write([]byte("ok\n"))
}

func (server *Server) sessionCookieName() string {
	if server.cfg.CookieSecure {
		return "__Host-ww_session"
	}
	return "ww_session"
}

func (server *Server) visitorCookieName() string {
	if server.cfg.CookieSecure {
		return "__Host-ww_visitor"
	}
	return "ww_visitor"
}

func (server *Server) setSessionCookie(writer http.ResponseWriter, credential identity.Credential) {
	http.SetCookie(writer, &http.Cookie{
		Name: server.sessionCookieName(), Value: credential.Token, Path: "/",
		Secure: server.cfg.CookieSecure, HttpOnly: true, SameSite: http.SameSiteLaxMode,
		Expires: credential.ExpiresAt,
	})
}

func (server *Server) setVisitorCookie(writer http.ResponseWriter, credential identity.Credential) {
	http.SetCookie(writer, &http.Cookie{
		Name: server.visitorCookieName(), Value: credential.Token, Path: "/",
		Secure: server.cfg.CookieSecure, HttpOnly: true, SameSite: http.SameSiteLaxMode,
		Expires: credential.ExpiresAt,
	})
}

func (server *Server) clearSessionCookie(writer http.ResponseWriter) {
	http.SetCookie(writer, &http.Cookie{Name: server.sessionCookieName(), Value: "", Path: "/", Secure: server.cfg.CookieSecure, HttpOnly: true, SameSite: http.SameSiteLaxMode, MaxAge: -1})
}

func (server *Server) clearVisitorCookie(writer http.ResponseWriter) {
	http.SetCookie(writer, &http.Cookie{Name: server.visitorCookieName(), Value: "", Path: "/", Secure: server.cfg.CookieSecure, HttpOnly: true, SameSite: http.SameSiteLaxMode, MaxAge: -1})
}

